import { existsSync } from 'node:fs';
import { AuthoritativeLedger, deepClone, deepFreeze } from './ledger.mjs';
import { invoke } from './runner.mjs';

/**
 * Isolated 44E coordinator owned by Steamroller; not a default runtime entry or
 * 44G activation. The exact-role adapter uses invoke(role, packet, options) and
 * returns {ok, response}. Bobcat remains native inside Bulldozer's invocation.
 * invokeZen is a required independent host-native call returning Zen's packet,
 * never a worker's relay. Children receive neither the ledger API nor its path.
 */
export class MinimalSpine {
  #ledger;
  #path;
  #invokeRole;
  #invokeZen;
  #runnerOptions;
  #busy = false;

  constructor({ ledgerPath, plan, invokeRole = invoke, invokeZen, runnerOptions = {} }) {
    if (typeof ledgerPath !== 'string' || !ledgerPath.trim()) {
      throw new TypeError('A supervisor-owned ledgerPath is required');
    }
    if (typeof invokeZen !== 'function') {
      throw new TypeError('An independent native Zen invocation is required');
    }
    this.#path = ledgerPath;
    this.#invokeRole = invokeRole;
    this.#invokeZen = invokeZen;
    this.#runnerOptions = runnerOptions;
    if (plan !== undefined) {
      if (existsSync(ledgerPath)) throw new Error('Refusing to replace an existing ledger');
      this.#ledger = new AuthoritativeLedger(plan);
      this.#ledger.save(this.#path);
    } else {
      this.#ledger = AuthoritativeLedger.load(ledgerPath);
    }
  }

  get state() {
    return deepFreeze(deepClone(this.#ledger.getState()));
  }

  #idle() {
    if (this.#busy || this.state.current_milestone !== null) {
      throw new Error('Execution or review is already active');
    }
  }

  async #exact(role, instruction, contract) {
    // The runner retains task text, not arbitrary packet fields. Serialize the
    // whole contract into task so bounded prompt construction keeps its fields.
    const output = await this.#invokeRole(role, {
      task: instruction + '\n' + JSON.stringify(contract),
    }, this.#runnerOptions);
    if (!output?.ok) {
      throw new Error(`${role} invocation failed: ${JSON.stringify(output)}`);
    }
    const packet = JSON.parse(output.response);
    if (!packet || typeof packet !== 'object' || Array.isArray(packet)) {
      throw new TypeError(`${role} must return a JSON object`);
    }
    return packet;
  }

  /** A planning response is advice; only explicit supervisor adoption changes state. */
  async requestPlan(task) {
    this.#idle();
    if (typeof task !== 'string' || !task.trim()) throw new TypeError('Planning task required');
    this.#busy = true;
    try {
      return await this.#exact('piledriver',
        'Return a bounded advisory plan as JSON. Do not implement, delegate workers, '
        + 'write ledger state, or claim completion.', { task, ledger: this.state });
    } finally {
      this.#busy = false;
    }
  }

  /** DONE is explicit candidate status, never automatic verified completion. */
  async runMilestone(milestoneId) {
    this.#idle();
    const contract = this.#ledger.delegate(milestoneId);
    this.#ledger.save(this.#path);
    this.#busy = true;
    try {
      const candidate = await this.#exact('bulldozer',
        'Execute only this milestone. Delegate bounded implementation to native '
        + 'Bobcat; set ADVISOR_GATE REQUIRED for substantive work or NONE only for '
        + 'low-risk mechanical work. Bobcat may invoke only Strix Halo when required. '
        + 'If a required specialist is unavailable, return BLOCKED, not a gate waiver. '
        + 'Inspect Bobcat results and actual evidence yourself. Worker READY and '
        + 'Strix ACCEPT are not DONE. Return your own JSON result packet with '
        + 'milestone_id, plan_version, explicit status DONE|BLOCKED|NEEDS_DEEP, '
        + 'changes_made, verification_evidence, unresolved_unknowns, scope_deviations, '
        + 'blockers and escalation_needs as applicable. DONE must identify immutable '
        + 'delivered artifact versions in candidate_artifact_ref. Do not invoke Zen, '
        + 'supply Zen authority, write the ledger, or claim global completion.', contract);

      if (candidate.milestone_id !== contract.milestone_id
          || candidate.plan_version !== contract.plan_version) {
        throw new Error('Candidate does not match the active milestone and plan');
      }
      // Preserve ingress status. Missing status, READY, and local advisor verdicts
      // cannot be normalized to DONE or used to skip the independent review.
      if (candidate.status === 'BLOCKED' || candidate.status === 'NEEDS_DEEP') {
        this.#ledger.recordBlockedOrFailure({
          milestoneId, status: candidate.status, blockers: candidate.blockers,
          escalationNeeds: candidate.escalation_needs, evidence: candidate,
        });
        this.#ledger.save(this.#path);
        return { status: candidate.status, candidate: deepClone(candidate), verified: false };
      }
      if (candidate.status !== 'DONE') {
        throw new Error('Only explicit Bulldozer DONE may enter Zen review');
      }
      if ('verdict' in candidate || 'zen_verdict' in candidate || 'result_ref' in candidate) {
        throw new Error('Bulldozer cannot issue result references or Zen authority');
      }
      if (typeof candidate.candidate_artifact_ref !== 'string'
          || !candidate.candidate_artifact_ref.trim()) {
        throw new Error('DONE must bind immutable delivered artifact versions');
      }
      const { result_ref, candidate_record } = this.#ledger.receiveCandidate(candidate);
      // The immutable candidate binding must be durable before Zen is invoked.
      this.#ledger.save(this.#path);
      const request = deepFreeze(deepClone({
        milestone_id: contract.milestone_id,
        plan_version: contract.plan_version,
        result_ref,
        contract,
        candidate: candidate_record,
      }));
      const verdict = deepClone(await this.#invokeZen(request));
      if (verdict?.verdict !== 'GO' && verdict?.verdict !== 'NO-GO') {
        throw new Error('Zen must return an observed GO or NO-GO');
      }
      if (verdict.milestone_id !== contract.milestone_id
          || verdict.plan_version !== contract.plan_version
          || verdict.result_ref !== result_ref) {
        throw new Error('Zen verdict does not match the current candidate binding');
      }
      if (!Array.isArray(verdict.verification_evidence)
          || !verdict.verification_evidence.length
          || !verdict.verification_evidence.every(item => item?.classification === 'OBSERVED')) {
        throw new Error('Zen must supply directly observed verification evidence');
      }
      if (verdict.verdict === 'GO') this.#ledger.recordZenGo(verdict);
      else this.#ledger.recordZenNoGo(verdict);
      this.#ledger.save(this.#path);
      return { status: 'DONE', result_ref, verdict, verified: verdict.verdict === 'GO' };
    } catch (error) {
      if (this.state.current_milestone === milestoneId) {
        this.#ledger.recordBlockedOrFailure({
          milestoneId, status: 'INVOCATION_FAILURE',
          evidence: { classification: 'OBSERVED', error: String(error) },
        });
        this.#ledger.save(this.#path);
      }
      throw error;
    } finally {
      this.#busy = false;
    }
  }

  /** Fresh-context recovery needs observed interruption, not a silent retry. */
  endInterruptedInvocation(evidence) {
    if (this.#busy) throw new Error('Cannot interrupt a live invocation through resume recovery');
    if (evidence?.classification !== 'OBSERVED') throw new Error('Observed interruption evidence required');
    const milestoneId = this.state.current_milestone;
    if (milestoneId === null) throw new Error('No interrupted invocation');
    this.#ledger.recordBlockedOrFailure({ milestoneId, status: 'INVOCATION_FAILURE', evidence });
    this.#ledger.save(this.#path);
  }

  adoptReplan(plan) {
    this.#idle();
    this.#ledger.materialReplan(plan);
    this.#ledger.save(this.#path);
    return this.state;
  }

  resolveBlocker(id, evidence) {
    this.#idle();
    if (evidence?.classification !== 'OBSERVED') throw new Error('Observed resolution evidence required');
    const resolution = this.#ledger.resolveBlocker(id, evidence);
    this.#ledger.save(this.#path);
    return resolution;
  }

  declareGlobalCompletion() {
    this.#idle();
    return this.#ledger.declareGlobalCompletion();
  }
}

import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";
import { TextDecoder } from "node:util";

// Explicitly bounded to the three runner roles; native specialists stay native.
const ROLE_BODY_ROLES = Object.freeze(["steamroller", "piledriver", "bulldozer"]);
const RUNNER_DIR = dirname(fileURLToPath(import.meta.url));

/**
 * Role policy table mapping agent roles to target model families and reasoning effort requirements.
 * Used for runtime resolution against the installed AGY surface (`agy models`).
 */
export const ROLE_POLICY_TABLE = Object.freeze({
  piledriver: Object.freeze({
    role: "piledriver",
    family: "Gemini 3.1 Pro",
    effort: "High",
  }),
  bulldozer: Object.freeze({
    role: "bulldozer",
    family: "Gemini 3.8 Flash",
    effort: "High",
  }),
  steamroller: Object.freeze({
    role: "steamroller",
    family: "Gemini 3.8 Flash",
    effort: "High",
  }),
});

/**
 * @deprecated Hard-coded slug lookup table is removed as the primary lookup.
 * Model slugs are resolved at runtime against installed AGY surface via ROLE_POLICY_TABLE.
 */
export const ROLE_MODEL_TABLE = Object.freeze({});

export class UnresolvedModelSlugError extends Error {
  constructor(role, message, details = {}) {
    super(message || `Unresolved model slug for role: ${role}`);
    this.name = "UnresolvedModelSlugError";
    this.ok = false;
    this.error = "UNRESOLVED_MODEL_SLUG";
    this.role = role;
    if (details && typeof details === "object") {
      Object.assign(this, details);
    }
  }
}

export class InvalidHandoffPacketError extends Error {
  constructor(message, details = {}) {
    super(message || "Invalid handoff packet");
    this.name = "InvalidHandoffPacketError";
    this.ok = false;
    this.error = "INVALID_HANDOFF_PACKET";
    if (details && typeof details === "object") {
      Object.assign(this, details);
    }
  }
}

export class RoleBodyError extends Error {
  constructor(role, error, message) {
    super(message);
    this.name = "RoleBodyError";
    this.ok = false;
    this.error = error;
    this.role = role;
  }
}

/**
 * Loads the role file as Markdown content, without interpreting AGY frontmatter.
 * Directory precedence: roleBodyDir, opts.env.NTG_ROLE_BODY_DIR, process env,
 * then ../agents relative to this module. Relative overrides also use RUNNER_DIR,
 * never the invocation cwd. Missing/invalid files never fall back to defaults.
 */
function loadRoleBody(role, opts) {
  const normalized = typeof role === "string" ? role.trim().toLowerCase() : "";
  if (!ROLE_BODY_ROLES.includes(normalized)) {
    throw new UnresolvedModelSlugError(role, `Unknown runner role: "${role}".`);
  }

  try {
    const directory = opts.roleBodyDir ?? opts.env?.NTG_ROLE_BODY_DIR ??
      process.env.NTG_ROLE_BODY_DIR ?? "../agents";
    if (typeof directory !== "string" || !directory.trim()) {
      throw new Error("Role body directory must be a non-empty path string");
    }
    const path = resolve(RUNNER_DIR, directory, `${normalized}.md`);
    const body = new TextDecoder("utf-8", { fatal: true }).decode(readFileSync(path));
    if (!body.trim() || /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(body)) {
      throw new Error("Role body must contain non-empty UTF-8 Markdown without non-text control characters");
    }
    return body.trim();
  } catch (err) {
    throw new RoleBodyError(
      role,
      err.code === "ENOENT" ? "ROLE_BODY_MISSING" : "ROLE_BODY_INVALID",
      `Cannot load role body for "${normalized}": ${err.message}`
    );
  }
}

/**
 * Parses raw stdout from `agy models` into an array of model entries.
 *
 * @param {string} stdout
 * @returns {Array<{ slug: string, description: string }>}
 */
export function parseInstalledModels(stdout) {
  if (typeof stdout !== "string") {
    return [];
  }
  const lines = stdout.split(/\r?\n/);
  const models = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    if (/^fetching\b/i.test(trimmed)) continue;
    // Slugs contain no whitespace. First non-whitespace sequence is the slug; the remainder is the description.
    const match = trimmed.match(/^(\S+)(?:\s+(.*))?$/);
    if (match) {
      models.push({
        slug: match[1],
        description: (match[2] || "").trim(),
      });
    }
  }
  return models;
}

/**
 * Discovers installed models by querying `agy models` at runtime.
 *
 * @param {object} [opts]
 * @param {string} [opts.agyPath] - Path to agy executable (defaults to AGY_PATH env or "agy")
 * @param {number} [opts.timeout=15000] - Discovery timeout in ms
 * @param {object} [opts.env] - Additional environment variables
 * @param {string} [opts.cwd] - Working directory
 * @returns {Array<{ slug: string, description: string }>}
 */
export function listInstalledModels(opts = {}) {
  const agyPath = opts.agyPath || process.env.AGY_PATH || "agy";
  const timeout = typeof opts.timeout === "number" ? opts.timeout : 15000;

  const result = spawnSync(agyPath, ["models"], {
    timeout,
    env: { ...process.env, ...(opts.env || {}) },
    cwd: opts.cwd || process.cwd(),
    encoding: "utf-8",
    maxBuffer: 5 * 1024 * 1024,
  });

  if (result.error) {
    throw new Error(`Failed to list installed models: ${result.error.message}`);
  }
  if (result.status !== 0) {
    throw new Error(
      `Failed to list installed models (exit code ${result.status}): ${result.stderr || ""}`
    );
  }

  return parseInstalledModels(result.stdout || "");
}

/**
 * Evaluates whether a candidate model entry satisfies a role policy specification.
 *
 * @param {object} policy - Role policy from ROLE_POLICY_TABLE
 * @param {string|{ slug: string, description?: string }} model
 * @returns {boolean}
 */
export function matchesPolicy(policy, model) {
  if (!policy || !model) return false;

  const slug = (typeof model === "string" ? model : model.slug || "").trim().toLowerCase();
  const desc = (typeof model === "object" && model && model.description ? model.description : "").trim().toLowerCase();

  const familySlug = policy.family.toLowerCase().replace(/[^a-z0-9.]+/g, "-");
  const familyText = policy.family.toLowerCase();
  const effort = policy.effort.toLowerCase();

  const familyMatch = slug.includes(familySlug) || (desc.length > 0 && desc.includes(familyText));
  if (!familyMatch) return false;

  const effortMatch =
    slug.endsWith(`-${effort}`) ||
    slug.includes(`-${effort}-`) ||
    (desc.length > 0 &&
      (desc.includes(`(${effort})`) || desc.includes(` ${effort} `) || desc.endsWith(` ${effort}`)));

  return effortMatch;
}

/**
 * Resolves a role name to its exact AGY model slug against the installed AGY surface.
 * Case-insensitive. Throws structured UnresolvedModelSlugError if 0 matches, ambiguous matches,
 * or unknown role. No silent fallback.
 *
 * @param {string} role - Role name (e.g. 'piledriver', 'bulldozer', 'steamroller')
 * @param {object} [opts] - Resolution options
 * @param {Array<string|object>} [opts.installedModels] - Optional pre-fetched/cached model surface for deterministic testing
 * @param {string} [opts.agyPath] - Path to agy executable
 * @returns {string} Exact model slug
 */
export function resolveSlug(role, opts = {}) {
  const normalized = typeof role === "string" ? role.trim().toLowerCase() : "";
  const policy = ROLE_POLICY_TABLE[normalized];
  if (!ROLE_BODY_ROLES.includes(normalized)) {
    throw new UnresolvedModelSlugError(
      role,
      `Unknown role: "${role}". No role policy defined.`
    );
  }

  let installed = opts.installedModels;
  if (!installed) {
    try {
      installed = listInstalledModels(opts);
    } catch (err) {
      throw new UnresolvedModelSlugError(
        role,
        `Failed to discover installed models for role "${role}": ${err.message}`,
        { cause: err }
      );
    }
  }

  if (!Array.isArray(installed)) {
    installed = [installed];
  }

  const matches = installed.filter((m) => matchesPolicy(policy, m));
  if (matches.length === 0) {
    throw new UnresolvedModelSlugError(
      role,
      `No installed model found matching policy for role "${role}" (family: "${policy.family}", effort: "${policy.effort}").`,
      { reason: "NOT_FOUND" }
    );
  }

  if (matches.length > 1) {
    const candidateSlugs = matches.map((m) => (typeof m === "string" ? m : m.slug));
    throw new UnresolvedModelSlugError(
      role,
      `Ambiguous model slug resolution for role "${role}": multiple matching models found: ${candidateSlugs.join(", ")}`,
      { reason: "AMBIGUOUS", matches: candidateSlugs }
    );
  }

  const resolved = matches[0];
  return typeof resolved === "string" ? resolved : resolved.slug;
}

/**
 * Composes a deterministic bounded prompt from the role body and handoff packet.
 * Enforces packet contract and strictly forbids raw conversational state.
 *
 * @param {string} role - Role name
 * @param {object} packet - Structured handoff packet
 * @param {object} [opts] - roleBodyDir / env options (see loadRoleBody)
 * @returns {string} Deterministically formatted bounded prompt
 */
export function composeBoundedPrompt(role, packet, opts = {}) {
  if (!packet || typeof packet !== "object" || Array.isArray(packet)) {
    throw new InvalidHandoffPacketError("Handoff packet must be a non-null object");
  }

  const FORBIDDEN_KEYS = ["messages", "conversation", "history", "transcript"];
  for (const forbidden of FORBIDDEN_KEYS) {
    if (forbidden in packet && packet[forbidden] !== undefined) {
      throw new InvalidHandoffPacketError(
        `Forbidden conversational state field in handoff packet: "${forbidden}". Raw conversational state is prohibited.`
      );
    }
  }

  const roleName = typeof role === "string" ? role.trim() : String(role || "");
  const task =
    typeof packet.task === "string"
      ? packet.task.trim()
      : typeof packet.objective === "string"
      ? packet.objective.trim()
      : "";
  if (!task) {
    throw new InvalidHandoffPacketError(
      "Handoff packet requires a non-empty 'task' or 'objective' string"
    );
  }

  const sections = [];

  if (roleName) {
    sections.push(`## Role\n${roleName}`);
  }

  sections.push(`## Role Body\n${loadRoleBody(role, opts)}`);
  sections.push(`## Task\n${task}`);

  const contextFiles = packet.contextFiles ?? packet.context_files;
  if (contextFiles) {
    if (Array.isArray(contextFiles) && contextFiles.length > 0) {
      sections.push(`## Context Files\n${contextFiles.map((f) => `- ${f}`).join("\n")}`);
    } else if (typeof contextFiles === "string" && contextFiles.trim()) {
      sections.push(`## Context Files\n${contextFiles.trim()}`);
    }
  }

  const evidence = packet.evidence;
  if (evidence) {
    if (Array.isArray(evidence) && evidence.length > 0) {
      sections.push(`## Evidence\n${evidence.map((e) => `- ${e}`).join("\n")}`);
    } else if (typeof evidence === "string" && evidence.trim()) {
      sections.push(`## Evidence\n${evidence.trim()}`);
    } else if (typeof evidence === "object" && Object.keys(evidence).length > 0) {
      sections.push(`## Evidence\n${JSON.stringify(evidence, null, 2)}`);
    }
  }

  const constraints = packet.constraints;
  if (constraints) {
    if (Array.isArray(constraints) && constraints.length > 0) {
      sections.push(`## Constraints\n${constraints.map((c) => `- ${c}`).join("\n")}`);
    } else if (typeof constraints === "string" && constraints.trim()) {
      sections.push(`## Constraints\n${constraints.trim()}`);
    }
  }

  const expectedOutput = packet.expectedOutput ?? packet.expected_output;
  if (expectedOutput) {
    if (Array.isArray(expectedOutput) && expectedOutput.length > 0) {
      sections.push(`## Expected Output\n${expectedOutput.map((o) => `- ${o}`).join("\n")}`);
    } else if (typeof expectedOutput === "string" && expectedOutput.trim()) {
      sections.push(`## Expected Output\n${expectedOutput.trim()}`);
    }
  }

  return sections.join("\n\n");
}

/**
 * Validates and parses the JSON response envelope from an AGY execution.
 * Only SUCCESS with valid string response succeeds. Any other status, unparseable JSON,
 * or malformed envelope returns structured INVALID_OUTPUT or MODEL_ERROR failure.
 *
 * @param {string} stdout - Raw stdout from agy
 * @param {object} [meta] - Context metadata (role, slug)
 * @returns {object} Structured result
 */
export function parseResponseEnvelope(stdout, meta = {}) {
  const role = meta.role;
  const slug = meta.slug;

  let parsed;
  try {
    parsed = JSON.parse(stdout.trim());
  } catch (parseErr) {
    return {
      ok: false,
      error: "INVALID_OUTPUT",
      ...(role ? { role } : {}),
      ...(slug ? { slug } : {}),
      message: `Failed to parse JSON response: ${parseErr.message}`,
      raw: stdout,
    };
  }

  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    return {
      ok: false,
      error: "INVALID_OUTPUT",
      ...(role ? { role } : {}),
      ...(slug ? { slug } : {}),
      message: "JSON response is not a valid object envelope",
      raw: parsed,
    };
  }

  if (parsed.status === "ERROR") {
    return {
      ok: false,
      error: "MODEL_ERROR",
      ...(role ? { role } : {}),
      ...(slug ? { slug } : {}),
      details: parsed,
    };
  }

  if (parsed.status === "SUCCESS") {
    if (typeof parsed.response !== "string") {
      return {
        ok: false,
        error: "INVALID_OUTPUT",
        ...(role ? { role } : {}),
        ...(slug ? { slug } : {}),
        message: "Missing or invalid 'response' field in SUCCESS envelope",
        details: parsed,
      };
    }

    return {
      ok: true,
      ...(role ? { role } : {}),
      ...(slug ? { slug } : {}),
      response: parsed.response,
      duration: parsed.duration_seconds,
      usage: parsed.usage,
      raw: parsed,
    };
  }

  return {
    ok: false,
    error: "INVALID_OUTPUT",
    ...(role ? { role } : {}),
    ...(slug ? { slug } : {}),
    message: `Unexpected response status: "${parsed.status}"`,
    details: parsed,
  };
}

/**
 * Low-level transport helper that executes the `agy` process directly with raw prompt,
 * handling timeout, recursion protection, and envelope parsing.
 *
 * Supports both signatures:
 * - invokeTransport({ slug, prompt, ...opts })
 * - invokeTransport(slug, prompt, opts)
 *
 * @param {string|object} slugOrOpts
 * @param {string} [maybePrompt]
 * @param {object} [maybeOpts]
 * @returns {object} Structured result
 */
export function invokeTransport(slugOrOpts, maybePrompt, maybeOpts) {
  let slug;
  let prompt;
  let opts;

  if (typeof slugOrOpts === "object" && slugOrOpts !== null) {
    opts = slugOrOpts;
    slug = opts.slug;
    prompt = opts.prompt;
  } else {
    slug = slugOrOpts;
    prompt = maybePrompt;
    opts = maybeOpts || {};
  }

  const role = opts.role;
  const timeout = typeof opts.timeout === "number" ? opts.timeout : 90000;
  const outputFormat = opts.outputFormat || "json";
  const agyPath = opts.agyPath || process.env.AGY_PATH || "agy";

  // Recursion protection
  const chainRaw = process.env.NTG_RUNNER_CHAIN;
  if (role && chainRaw) {
    const normalizedRole = typeof role === "string" ? role.trim().toLowerCase() : String(role);
    const parts = chainRaw.split(":").map((s) => s.trim().toLowerCase()).filter(Boolean);
    if (parts.includes(normalizedRole)) {
      return {
        ok: false,
        error: "RECURSION_DETECTED",
        role,
        chain: chainRaw,
      };
    }
  }

  const nextChain = role ? (chainRaw ? `${chainRaw}:${role}` : role) : chainRaw;
  const childEnv = {
    ...process.env,
    ...(opts.env || {}),
    ...(nextChain ? { NTG_RUNNER_CHAIN: nextChain } : {}),
  };

  const args = [
    "--model",
    slug,
    "--output-format",
    outputFormat,
    "--print",
    prompt,
  ];

  let result;
  try {
    result = spawnSync(agyPath, args, {
      timeout,
      env: childEnv,
      cwd: opts.cwd || process.cwd(),
      encoding: "utf-8",
      maxBuffer: 20 * 1024 * 1024,
    });
  } catch (err) {
    return {
      ok: false,
      error: "SPAWN_ERROR",
      ...(role ? { role } : {}),
      slug,
      message: err.message,
    };
  }

  if (result.error) {
    if (result.error.code === "ETIMEDOUT") {
      return {
        ok: false,
        error: "TIMEOUT",
        ...(role ? { role } : {}),
        slug,
        timeout,
      };
    }
    return {
      ok: false,
      error: "SPAWN_ERROR",
      ...(role ? { role } : {}),
      slug,
      message: result.error.message,
    };
  }

  if (result.status !== 0) {
    return {
      ok: false,
      error: "EXECUTION_FAILED",
      ...(role ? { role } : {}),
      slug,
      exitCode: result.status,
      stderr: (result.stderr || "").toString(),
    };
  }

  const stdout = (result.stdout || "").toString();

  if (outputFormat === "json") {
    return parseResponseEnvelope(stdout, { role, slug });
  }

  return {
    ok: true,
    ...(role ? { role } : {}),
    slug,
    response: stdout,
  };
}

/**
 * Contract-level runner that validates and resolves slug via role policy,
 * validates the handoff packet, loads the role body, composes a bounded prompt,
 * and executes via invokeTransport.
 *
 * @param {string} role - Target role (e.g. 'piledriver', 'bulldozer', 'steamroller')
 * @param {object} packet - Structured handoff packet ({ task, ... })
 * @param {object} [opts] - Invocation options, including roleBodyDir / env overrides
 * @returns {object} Structured result
 */
export function invoke(role, packet, opts = {}) {
  const options = opts || {};
  if (options.outputFormat && options.outputFormat !== "json") {
    return {
      ok: false,
      error: "INVALID_OUTPUT_FORMAT",
      role,
      message:
        "invoke() requires JSON output format; envelope validation cannot be bypassed. Use invokeTransport() if text format is needed.",
    };
  }

  // Recursion protection early check
  const normalizedRole = typeof role === "string" ? role.trim().toLowerCase() : String(role);
  const chainRaw = process.env.NTG_RUNNER_CHAIN;
  if (chainRaw) {
    const parts = chainRaw.split(":").map((s) => s.trim().toLowerCase()).filter(Boolean);
    if (parts.includes(normalizedRole)) {
      return {
        ok: false,
        error: "RECURSION_DETECTED",
        role,
        chain: chainRaw,
      };
    }
  }

  // Slug resolution
  let slug;
  try {
    slug = resolveSlug(role, options);
  } catch (err) {
    return {
      ok: false,
      error: err.error || "UNRESOLVED_MODEL_SLUG",
      role,
      message: err.message,
      ...(err.matches ? { matches: err.matches } : {}),
    };
  }

  // Packet validation & bounded prompt composition
  let prompt;
  try {
    prompt = composeBoundedPrompt(role, packet, options);
  } catch (err) {
    return {
      ok: false,
      error: err.error || "INVALID_HANDOFF_PACKET",
      role,
      message: err.message,
    };
  }

  return invokeTransport({
    ...options,
    slug,
    prompt,
    role,
    outputFormat: "json",
  });
}

// CLI execution support
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const [, , role, ...promptParts] = process.argv;
  if (!role || promptParts.length === 0) {
    console.error("Usage: node scripts/runner.mjs <role> <prompt>");
    process.exit(1);
  }

  const prompt = promptParts.join(" ");
  const res = invoke(role, { task: prompt });
  if (res.ok) {
    if (typeof res.response === "string") {
      process.stdout.write(res.response);
    } else {
      console.log(JSON.stringify(res, null, 2));
    }
    process.exitCode = 0;
  } else {
    console.error(JSON.stringify(res, null, 2));
    process.exitCode = 1;
  }
}

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";

/**
 * Structured error classes for authoritative ledger transitions and invariant enforcement.
 */
export class InvalidTransitionError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = "InvalidTransitionError";
    this.code = "INVALID_TRANSITION";
    Object.assign(this, details);
  }
}

export class StaleVerdictError extends InvalidTransitionError {
  constructor(message, details = {}) {
    super(message, details);
    this.name = "StaleVerdictError";
    this.code = "STALE_VERDICT";
  }
}

export class MismatchedResultRefError extends InvalidTransitionError {
  constructor(message, details = {}) {
    super(message, details);
    this.name = "MismatchedResultRefError";
    this.code = "MISMATCHED_RESULT_REF";
  }
}

export class InvariantViolationError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = "InvariantViolationError";
    this.code = "INVARIANT_VIOLATION";
    Object.assign(this, details);
  }
}

export class RefRebindingError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = "RefRebindingError";
    this.code = "REF_REBINDING";
    Object.assign(this, details);
  }
}

export class BlockerNotFoundError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = "BlockerNotFoundError";
    this.code = "BLOCKER_NOT_FOUND";
    Object.assign(this, details);
  }
}

/**
 * Recursively freezes an object and its nested properties.
 *
 * @param {*} obj
 * @returns {*}
 */
export function deepFreeze(obj) {
  if (obj === null || typeof obj !== "object") {
    return obj;
  }
  Object.freeze(obj);
  for (const key of Object.getOwnPropertyNames(obj)) {
    const val = obj[key];
    if (val !== null && typeof val === "object" && !Object.isFrozen(val)) {
      deepFreeze(val);
    }
  }
  return obj;
}

/**
 * Creates a deep clone of a plain object or array.
 * Uses structuredClone if available, falling back to JSON roundtrip.
 *
 * @param {*} obj
 * @returns {*}
 */
export function deepClone(obj) {
  if (typeof structuredClone === "function") {
    return structuredClone(obj);
  }
  return JSON.parse(JSON.stringify(obj));
}

/**
 * Deterministic JSON stringifier that sorts object keys recursively.
 *
 * @param {*} obj
 * @returns {string}
 */
export function canonicalJson(obj) {
  if (obj === null || typeof obj !== "object") {
    return JSON.stringify(obj);
  }
  if (Array.isArray(obj)) {
    return "[" + obj.map(canonicalJson).join(",") + "]";
  }
  const keys = Object.keys(obj).sort();
  return "{" + keys.map((k) => JSON.stringify(k) + ":" + canonicalJson(obj[k])).join(",") + "}";
}

/**
 * Generates a unique, deterministic result_ref (SHA-256) from candidate payload and artifact ref.
 * Normalizes candidate_artifact_ref and artifact_ref aliases to candidate_artifact_ref prior to hashing.
 * Fails closed if both aliases are present with different values.
 *
 * @param {object} candidatePacket
 * @returns {string}
 */
export function generateResultRef(candidatePacket) {
  if (!candidatePacket || typeof candidatePacket !== "object" || Array.isArray(candidatePacket)) {
    throw new InvariantViolationError("Candidate packet must be an object to generate result_ref");
  }

  const hasCand = candidatePacket.candidate_artifact_ref !== undefined;
  const hasArt = candidatePacket.artifact_ref !== undefined;

  if (hasCand && hasArt && candidatePacket.candidate_artifact_ref !== candidatePacket.artifact_ref) {
    throw new InvariantViolationError(
      `Conflicting candidate artifact references: candidate_artifact_ref '${candidatePacket.candidate_artifact_ref}' vs artifact_ref '${candidatePacket.artifact_ref}'`
    );
  }

  const clone = { ...candidatePacket };
  delete clone.result_ref;
  delete clone.resultRef;
  delete clone.artifact_ref;

  const effectiveRef = hasCand ? candidatePacket.candidate_artifact_ref : candidatePacket.artifact_ref;
  if (effectiveRef !== undefined) {
    clone.candidate_artifact_ref = effectiveRef;
  } else {
    delete clone.candidate_artifact_ref;
  }

  const artifactRef = effectiveRef ?? "";
  const canonical = canonicalJson(clone) + "::" + String(artifactRef);
  const hash = createHash("sha256").update(canonical, "utf-8").digest("hex");
  return `ref-sha256-${hash}`;
}

/**
 * Checks if a verification_evidence value is missing or empty.
 * Empty includes: undefined, null, empty string, whitespace-only string,
 * empty array, or array where all elements are empty/whitespace.
 *
 * @param {*} evidence
 * @returns {boolean}
 */
export function isEvidenceEmpty(evidence) {
  if (evidence === undefined || evidence === null) {
    return true;
  }
  if (typeof evidence === "string") {
    return !evidence.trim();
  }
  if (Array.isArray(evidence)) {
    if (evidence.length === 0) {
      return true;
    }
    return evidence.every((item) => {
      if (item === undefined || item === null) return true;
      if (typeof item === "string") return !item.trim();
      return false;
    });
  }
  return true;
}

/**
 * Validates candidate semantic invariants shared between live ingress (receiveCandidate)
 * and persistence / resume verification (verifyCandidateIntegrity / fromJSON).
 *
 * @param {object} packet
 * @param {object} [opts]
 * @param {string} [opts.expectedMilestone]
 * @param {string|number} [opts.expectedPlanVersion]
 * @param {string} [opts.milestoneLabel="expected"]
 * @param {string} [opts.planVersionLabel="expected"]
 * @param {Function} [opts.errorClass=InvariantViolationError]
 * @returns {boolean}
 */
export function validateCandidateSemantics(packet, opts = {}) {
  const ErrorClass = opts.errorClass || InvariantViolationError;

  if (!packet || typeof packet !== "object" || Array.isArray(packet)) {
    throw new ErrorClass("Candidate packet must be an object");
  }

  const milestoneId = packet.milestone_id ?? packet.milestoneId;
  if (typeof milestoneId !== "string" || !milestoneId.trim()) {
    throw new ErrorClass("Candidate milestone_id must be a non-empty string");
  }
  if (
    opts.expectedMilestone !== undefined &&
    opts.expectedMilestone !== null &&
    milestoneId !== opts.expectedMilestone
  ) {
    const label = opts.milestoneLabel || "expected";
    throw new ErrorClass(
      `Candidate milestone_id '${milestoneId}' does not match ${label} milestone '${opts.expectedMilestone}'`
    );
  }

  const planVersion = packet.plan_version ?? packet.planVersion;
  if (planVersion === undefined || planVersion === null || planVersion === "") {
    throw new ErrorClass("Candidate plan_version must be present");
  }
  if (
    opts.expectedPlanVersion !== undefined &&
    opts.expectedPlanVersion !== null &&
    planVersion !== opts.expectedPlanVersion
  ) {
    const label = opts.planVersionLabel || "expected";
    throw new ErrorClass(
      `Candidate plan_version '${planVersion}' does not match ${label} plan_version '${opts.expectedPlanVersion}'`
    );
  }

  if (packet.status !== "DONE") {
    throw new ErrorClass(
      `Candidate packet status must be 'DONE' to enter candidate review path, got '${packet.status}'`
    );
  }

  // changes_made: must be provided (defined, non-null, Array or string)
  const changesMade = packet.changes_made;
  if (
    changesMade === undefined ||
    changesMade === null ||
    (!Array.isArray(changesMade) && typeof changesMade !== "string")
  ) {
    throw new ErrorClass(
      "Candidate changes_made must be provided as an Array or string"
    );
  }

  // verification_evidence: must be provided and CANNOT be empty
  if (isEvidenceEmpty(packet.verification_evidence)) {
    throw new ErrorClass(
      "Candidate verification_evidence must be provided and cannot be empty"
    );
  }

  // unresolved_unknowns: must be provided (defined, non-null, Array or string; [] is allowed)
  const unknowns = packet.unresolved_unknowns;
  if (
    unknowns === undefined ||
    unknowns === null ||
    (!Array.isArray(unknowns) && typeof unknowns !== "string")
  ) {
    throw new ErrorClass(
      "Candidate unresolved_unknowns must be provided as an Array or string"
    );
  }

  // scope_deviations: must be provided (defined, non-null, Array or string; [] is allowed)
  const deviations = packet.scope_deviations;
  if (
    deviations === undefined ||
    deviations === null ||
    (!Array.isArray(deviations) && typeof deviations !== "string")
  ) {
    throw new ErrorClass(
      "Candidate scope_deviations must be provided as an Array or string"
    );
  }

  // Check alias conflict fail-closed
  const hasCandArtifact = packet.candidate_artifact_ref !== undefined;
  const hasAliasArtifact = packet.artifact_ref !== undefined;
  if (
    hasCandArtifact &&
    hasAliasArtifact &&
    packet.candidate_artifact_ref !== packet.artifact_ref
  ) {
    throw new ErrorClass(
      `Conflicting candidate artifact references: candidate_artifact_ref '${packet.candidate_artifact_ref}' vs artifact_ref '${packet.artifact_ref}'`
    );
  }

  return true;
}

/**
 * Validates completed milestone Zen GO verification record semantic invariants.
 * Shared between live verification (recordZenGo) and persistence / resume (fromJSON).
 *
 * @param {object} verRecord
 * @param {object} [opts]
 * @param {string} [opts.expectedMilestone]
 * @param {string|number} [opts.expectedPlanVersion]
 * @param {string} [opts.expectedResultRef]
 * @param {Function} [opts.errorClass=InvariantViolationError]
 * @returns {boolean}
 */
export function validateZenGoSemantics(verRecord, opts = {}) {
  const ErrorClass = opts.errorClass || InvariantViolationError;

  if (!verRecord || typeof verRecord !== "object" || Array.isArray(verRecord)) {
    throw new ErrorClass("Zen GO verification record must be an object");
  }

  if (verRecord.verdict !== "GO") {
    throw new ErrorClass(
      `Zen GO verification record verdict must be 'GO', got '${verRecord.verdict}'`
    );
  }

  if (verRecord.is_stale) {
    throw new ErrorClass("Zen GO verification record cannot be stale");
  }

  const milestoneId = verRecord.milestone_id ?? verRecord.milestoneId;
  if (typeof milestoneId !== "string" || !milestoneId.trim()) {
    throw new ErrorClass("Zen GO verification milestone_id must be a non-empty string");
  }
  if (
    opts.expectedMilestone !== undefined &&
    opts.expectedMilestone !== null &&
    milestoneId !== opts.expectedMilestone
  ) {
    throw new ErrorClass(
      `Zen GO verification milestone_id '${milestoneId}' does not match expected milestone '${opts.expectedMilestone}'`
    );
  }

  const planVersion = verRecord.plan_version ?? verRecord.planVersion;
  if (planVersion === undefined || planVersion === null || planVersion === "") {
    throw new ErrorClass("Zen GO verification plan_version must be present");
  }
  if (
    opts.expectedPlanVersion !== undefined &&
    opts.expectedPlanVersion !== null &&
    planVersion !== opts.expectedPlanVersion
  ) {
    throw new ErrorClass(
      `Zen GO verification plan_version '${planVersion}' does not match expected plan_version '${opts.expectedPlanVersion}'`
    );
  }

  const resultRef = verRecord.result_ref ?? verRecord.resultRef;
  if (!resultRef || typeof resultRef !== "string" || !resultRef.trim()) {
    throw new ErrorClass("Zen GO verification result_ref must be a non-empty string");
  }
  if (
    opts.expectedResultRef !== undefined &&
    opts.expectedResultRef !== null &&
    resultRef !== opts.expectedResultRef
  ) {
    throw new ErrorClass(
      `Zen GO verification result_ref '${resultRef}' does not match expected candidate result_ref '${opts.expectedResultRef}'`
    );
  }

  if (isEvidenceEmpty(verRecord.verification_evidence)) {
    throw new ErrorClass(
      "Zen GO verification verification_evidence must be provided and cannot be empty"
    );
  }

  return true;
}

/**
 * Recomputes result_ref from candidate payload and artifact binding, verifying integrity.
 * Strictly verifies that candidate record and payload match across status, changes_made,
 * verification_evidence, unresolved_unknowns, scope_deviations, milestone_id, plan_version,
 * and artifact binding.
 * Throws InvariantViolationError if tampered or mismatched.
 *
 * @param {object} candidate
 * @param {string} [expectedRef]
 * @param {object} [opts]
 * @returns {string} Recomputed result_ref
 */
export function verifyCandidateIntegrity(candidate, expectedRef = null, opts = {}) {
  if (!candidate || typeof candidate !== "object" || Array.isArray(candidate)) {
    throw new InvariantViolationError("Candidate record must be an object");
  }
  const storedRef = candidate.result_ref || candidate.resultRef;
  if (!storedRef || typeof storedRef !== "string" || !storedRef.trim()) {
    throw new InvariantViolationError("Candidate record missing valid result_ref");
  }
  if (expectedRef && storedRef !== expectedRef) {
    throw new InvariantViolationError(
      `Candidate result_ref '${storedRef}' does not match expected result_ref '${expectedRef}'`
    );
  }

  // Validate payload existence
  if (!candidate.payload || typeof candidate.payload !== "object" || Array.isArray(candidate.payload)) {
    throw new InvariantViolationError("Candidate record missing valid payload object");
  }

  const payload = candidate.payload;

  // Validate candidate record semantics fail-closed
  validateCandidateSemantics(candidate, {
    expectedMilestone: opts.expectedMilestone,
    expectedPlanVersion: opts.expectedPlanVersion,
    errorClass: InvariantViolationError,
  });

  // Validate candidate payload semantics fail-closed
  validateCandidateSemantics(payload, {
    expectedMilestone: opts.expectedMilestone,
    expectedPlanVersion: opts.expectedPlanVersion,
    errorClass: InvariantViolationError,
  });

  // 1. Status strictly match
  if (!candidate.status || typeof candidate.status !== "string") {
    throw new InvariantViolationError("Candidate record status must be a non-empty string");
  }
  if (candidate.status !== payload.status) {
    throw new InvariantViolationError(
      `Candidate record status '${candidate.status}' does not match payload status '${payload.status}' (tampering detected)`
    );
  }

  // 2. Milestone ID strictly match
  const candMilestone = candidate.milestone_id ?? candidate.milestoneId;
  const payloadMilestone = payload.milestone_id ?? payload.milestoneId;
  if (!candMilestone || typeof candMilestone !== "string") {
    throw new InvariantViolationError("Candidate record missing milestone_id");
  }
  if (candMilestone !== payloadMilestone) {
    throw new InvariantViolationError(
      `Candidate record milestone_id '${candMilestone}' does not match payload milestone_id '${payloadMilestone}' (tampering detected)`
    );
  }

  // 3. Plan version strictly match
  const candVersion = candidate.plan_version ?? candidate.planVersion;
  const payloadVersion = payload.plan_version ?? payload.planVersion;
  if (candVersion === undefined || candVersion === null) {
    throw new InvariantViolationError("Candidate record missing plan_version");
  }
  if (candVersion !== payloadVersion) {
    throw new InvariantViolationError(
      `Candidate record plan_version '${candVersion}' does not match payload plan_version '${payloadVersion}' (tampering detected)`
    );
  }

  // 4. changes_made strictly match
  if (candidate.changes_made === undefined || candidate.changes_made === null) {
    throw new InvariantViolationError("Candidate record missing changes_made");
  }
  if (payload.changes_made === undefined || payload.changes_made === null) {
    throw new InvariantViolationError("Candidate payload missing changes_made");
  }
  const normCandChanges = Array.isArray(candidate.changes_made)
    ? candidate.changes_made
    : [candidate.changes_made];
  const normPayloadChanges = Array.isArray(payload.changes_made)
    ? payload.changes_made
    : [payload.changes_made];
  if (canonicalJson(normCandChanges) !== canonicalJson(normPayloadChanges)) {
    throw new InvariantViolationError(
      "Candidate record changes_made does not match payload changes_made (tampering detected)"
    );
  }

  // 5. verification_evidence strictly match
  if (candidate.verification_evidence === undefined || candidate.verification_evidence === null) {
    throw new InvariantViolationError("Candidate record missing verification_evidence");
  }
  if (payload.verification_evidence === undefined || payload.verification_evidence === null) {
    throw new InvariantViolationError("Candidate payload missing verification_evidence");
  }
  const normCandEv = Array.isArray(candidate.verification_evidence)
    ? candidate.verification_evidence
    : [candidate.verification_evidence];
  const normPayloadEv = Array.isArray(payload.verification_evidence)
    ? payload.verification_evidence
    : [payload.verification_evidence];
  if (canonicalJson(normCandEv) !== canonicalJson(normPayloadEv)) {
    throw new InvariantViolationError(
      "Candidate record verification_evidence does not match payload verification_evidence (tampering detected)"
    );
  }

  // 6. unresolved_unknowns strictly match
  if (candidate.unresolved_unknowns === undefined || candidate.unresolved_unknowns === null) {
    throw new InvariantViolationError("Candidate record missing unresolved_unknowns");
  }
  if (payload.unresolved_unknowns === undefined || payload.unresolved_unknowns === null) {
    throw new InvariantViolationError("Candidate payload missing unresolved_unknowns");
  }
  const normCandUnknowns = Array.isArray(candidate.unresolved_unknowns)
    ? candidate.unresolved_unknowns
    : [candidate.unresolved_unknowns];
  const normPayloadUnknowns = Array.isArray(payload.unresolved_unknowns)
    ? payload.unresolved_unknowns
    : [payload.unresolved_unknowns];
  if (canonicalJson(normCandUnknowns) !== canonicalJson(normPayloadUnknowns)) {
    throw new InvariantViolationError(
      "Candidate record unresolved_unknowns does not match payload unresolved_unknowns (tampering detected)"
    );
  }

  // 7. scope_deviations strictly match
  if (candidate.scope_deviations === undefined || candidate.scope_deviations === null) {
    throw new InvariantViolationError("Candidate record missing scope_deviations");
  }
  if (payload.scope_deviations === undefined || payload.scope_deviations === null) {
    throw new InvariantViolationError("Candidate payload missing scope_deviations");
  }
  const normCandDeviations = Array.isArray(candidate.scope_deviations)
    ? candidate.scope_deviations
    : [candidate.scope_deviations];
  const normPayloadDeviations = Array.isArray(payload.scope_deviations)
    ? payload.scope_deviations
    : [payload.scope_deviations];
  if (canonicalJson(normCandDeviations) !== canonicalJson(normPayloadDeviations)) {
    throw new InvariantViolationError(
      "Candidate record scope_deviations does not match payload scope_deviations (tampering detected)"
    );
  }

  // 8. Artifact binding strictly match and alias conflict check
  if (
    candidate.candidate_artifact_ref !== undefined &&
    candidate.artifact_ref !== undefined &&
    candidate.candidate_artifact_ref !== candidate.artifact_ref
  ) {
    throw new InvariantViolationError(
      `Candidate record conflicting artifact references: '${candidate.candidate_artifact_ref}' vs '${candidate.artifact_ref}'`
    );
  }

  if (
    payload.candidate_artifact_ref !== undefined &&
    payload.artifact_ref !== undefined &&
    payload.candidate_artifact_ref !== payload.artifact_ref
  ) {
    throw new InvariantViolationError(
      `Candidate payload conflicting artifact references: '${payload.candidate_artifact_ref}' vs '${payload.artifact_ref}'`
    );
  }

  const recordArtifactRef = candidate.candidate_artifact_ref ?? candidate.artifact_ref;
  const payloadArtifactRef = payload.candidate_artifact_ref ?? payload.artifact_ref;

  const normRecordRef = recordArtifactRef !== undefined ? recordArtifactRef : null;
  const normPayloadRef = payloadArtifactRef !== undefined ? payloadArtifactRef : null;

  if (normRecordRef !== normPayloadRef) {
    throw new InvariantViolationError(
      `Candidate artifact binding mismatch: record '${recordArtifactRef}' vs payload '${payloadArtifactRef}' (tampering detected)`
    );
  }

  // Recompute result_ref using generateResultRef on payload
  const recomputedRef = generateResultRef(payload);
  if (recomputedRef !== storedRef) {
    throw new InvariantViolationError(
      `Candidate result_ref integrity check failed: stored '${storedRef}', recomputed '${recomputedRef}' (tampered candidate payload or artifact binding)`
    );
  }

  if (expectedRef && recomputedRef !== expectedRef) {
    throw new InvariantViolationError(
      `Candidate result_ref integrity check failed: expected '${expectedRef}', recomputed '${recomputedRef}'`
    );
  }

  return recomputedRef;
}

/**
 * Monotonically increments plan_version identifier (e.g. 'v1' -> 'v2', 1 -> 2).
 *
 * @param {string|number} current
 * @returns {string|number}
 */
export function incrementPlanVersion(current) {
  if (typeof current === "number") {
    return current + 1;
  }
  const str = String(current || "v0").trim();
  const match = str.match(/^([a-zA-Z]*)(\d+)$/);
  if (match) {
    const prefix = match[1];
    const num = parseInt(match[2], 10);
    return `${prefix}${num + 1}`;
  }
  return `${str}.1`;
}

/**
 * Parses a plan version string or number into a prefix and integer number.
 * Supports formats like 'v1', 'v2', 'v9', 'v10', or numbers 1, 2.
 *
 * @param {string|number} v
 * @returns {{ prefix: string, num: number }|null}
 */
export function parseVersion(v) {
  if (typeof v === "number" && Number.isFinite(v)) {
    return { prefix: "", num: v };
  }
  const str = String(v ?? "").trim();
  const match = str.match(/^([a-zA-Z]*)(\d+)$/);
  if (match) {
    return { prefix: match[1], num: parseInt(match[2], 10) };
  }
  return null;
}

/**
 * Validates a plan specification: structure, milestone list, uniqueness, dependencies, and acyclicity.
 *
 * @param {object} plan
 */
export function validatePlan(plan) {
  if (!plan || typeof plan !== "object" || Array.isArray(plan)) {
    throw new InvariantViolationError("Plan must be a non-null object");
  }
  if (!plan.goal || typeof plan.goal !== "string" || !plan.goal.trim()) {
