#!/usr/bin/env python3
"""Marker-scoped AGY guard, independently authored from NTG's effect contract.

This denies known privilege drift, credential mining and broad upgrades, not
ordinary repair mutations. It is not a sandbox for arbitrary executable files.
"""
import json
import os
import re
import shlex
import sys

MARKER = "NTG_EXCAVATOR=1 "
GUIDANCE = "; continue available diagnostics, ask the user for authorization, or report BLOCKED"
SHELLS = {"sh", "bash", "dash", "zsh", "ksh", "fish"}


def inspect_script(script, depth=0):
    if depth > 16:
        return "Shell nesting exceeds inspection limit"
    lexer = shlex.shlex(script.replace("\n", ";"), posix=True,
                        punctuation_chars=";&|()<>")
    lexer.whitespace_split = True
    lexer.commenters = "#"
    words = list(lexer)
    # Expansions can synthesize executable names; fail closed rather than
    # guessing their runtime value. Literal quoted diagnostic text stays usable.
    if any("`" in word or "$" in word for word in words):
        return "Dynamic shell expansion cannot be inspected reliably"
    segments = []
    current = []
    piped = False
    for word in words:
        if word and all(char in ";&|()<>" for char in word):
            if current:
                segments.append((current, piped or "<" in word))
                current = []
            piped = "|" in word or "<" in word
        else:
            current.append(word)
    if current:
        segments.append((current, piped))
    for command, stdin_supplied in segments:
        reason = inspect_simple(command, stdin_supplied, depth)
        if reason:
            return reason
    return None


def inspect_simple(words, stdin_supplied, depth):
    words = list(words)
    while words:
        name = os.path.basename(words[0])
        if re.match(r"^[A-Za-z_][A-Za-z_0-9]*=", words[0]):
            words.pop(0)
            continue
        if name in {"command", "builtin", "exec", "env", "sudo"}:
            words.pop(0)
            if name == "sudo" and stdin_supplied:
                return "Piped or redirected sudo input is privilege acquisition"
            while words and words[0].startswith("-") and words[0] != "-":
                option = words.pop(0)
                if name == "sudo":
                    if option == "--stdin" or (not option.startswith("--") and "S" in option):
                        return "Non-interactive sudo password injection is forbidden"
                    if option in {"-u", "-g", "-h", "-p", "-C", "-T", "-R", "-D", "--user", "--group", "--host", "--prompt", "--chroot", "--chdir"} and words:
                        words.pop(0)
                elif name == "env" and option in {"-u", "--unset", "-C", "--chdir"} and words:
                    words.pop(0)
                elif name == "env" and option in {"-S", "--split-string"}:
                    return inspect_script(" ".join(words), depth + 1)
                if option == "--":
                    break
            continue
        break
    if not words:
        return None
    name, args = os.path.basename(words[0]), words[1:]
    if name in {"su", "pkexec", "doas"}:
        return "Alternate privilege acquisition is forbidden"
    if name in SHELLS:
        for index, arg in enumerate(args):
            if arg.startswith("-") and not arg.startswith("--") and "c" in arg:
                if index + 1 >= len(args):
                    return "Missing shell command body"
                return inspect_script(args[index + 1], depth + 1)
    if name == "eval":
        return inspect_script(" ".join(args), depth + 1)
    if name == "ssh":
        root = any(arg.startswith("root@") for arg in args)
        root = root or any(arg == "-lroot" or arg == "User=root" for arg in args)
        root = root or any(args[i:i + 2] == ["-l", "root"] for i in range(len(args)))
        local = any(arg.removeprefix("root@").strip("[]").lower() in
                    {"localhost", "localhost.localdomain", "127.0.0.1", "::1", "0.0.0.0"}
                    for arg in args)
        if root and local:
            return "Loopback root SSH is privilege acquisition"
    if name in {"cat", "grep", "rg", "head", "tail", "less", "more", "awk", "sed", "strings", "cp"}:
        if any(re.search(r"(?:^|/)(?:\.[^/]*history|[^/]*history[^/]*)$", arg, re.I) for arg in args):
            return "Reading interactive shell history risks credential mining"
    if name in {"history", "fc"}:
        return "Interactive shell history is not an authorized credential source"
    if name in {"apt", "apt-get", "yum", "dnf", "dnf5", "zypper"}:
        if any(arg in {"upgrade", "full-upgrade", "dist-upgrade", "system-upgrade", "update", "dup"} for arg in args):
            # apt update refreshes metadata, not the installed system.
            if not (name in {"apt", "apt-get"} and "update" in args and not any(
                    arg in {"upgrade", "full-upgrade", "dist-upgrade"} for arg in args)):
                return "Exploratory full-system upgrades are forbidden"
    if name in {"pacman", "yay", "paru"}:
        if any(arg == "--sysupgrade" or (arg.startswith("-") and not arg.startswith("--") and "u" in arg) for arg in args):
            return "Exploratory full-system upgrades are forbidden"
    return None


def evaluate(payload):
    if not isinstance(payload, dict) or not isinstance(payload.get("toolCall"), dict):
        raise ValueError("Expected AGY toolCall object")
    call = payload["toolCall"]
    if not isinstance(call.get("name"), str):
        raise ValueError("Expected tool name")
    if call["name"] != "run_command":
        return {"decision": "allow", "reason": "Not a shell tool"}
    args = call.get("args")
    if not isinstance(args, dict) or not isinstance(args.get("CommandLine"), str):
        raise ValueError("Expected toolCall.args.CommandLine string")
    command = args["CommandLine"]
    if not command.startswith(MARKER):
        return {"decision": "allow", "reason": "Outside the Excavator-marked boundary"}
    script = command[len(MARKER):]
    if not script.strip():
        raise ValueError("Empty marked shell command")
    reason = inspect_script(script)
    if reason:
        return {"decision": "deny", "reason": reason + GUIDANCE}
    return {"decision": "allow", "reason": "No prohibited Excavator effect detected"}


def main():
    try:
        result = evaluate(json.load(sys.stdin))
    except (ValueError, TypeError, RecursionError) as error:
        result = {"decision": "deny", "reason": "Malformed hook input: " + str(error) + GUIDANCE}
    print(json.dumps(result))


if __name__ == "__main__":
    main()

{
  "name": "native-gravity",
  "version": "0.4.3",
  "description": "A thin Antigravity-native orchestration plugin with delegated implementation and independent verification."
}

#!/usr/bin/env node
import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { AuthoritativeLedger, InvalidTransitionError } from './ledger.mjs';
import { MinimalSpine } from './spine.mjs';
import { invoke } from './runner.mjs';

const optionsByCommand = {
  init: ['plan'], status: [], delegate: ['milestone'],
  'run-milestone': ['milestone', 'zen-cmd'], candidate: ['file'],
  'record-zen': ['file'], blocked: ['milestone', 'status', 'blocker', 'evidence'],
  replan: ['plan'], 'resolve-blocker': ['id', 'evidence'], complete: [],
  'invoke-role': ['role', 'packet'],
};
const readJson = path => JSON.parse(readFileSync(path, 'utf8'));

function parseArgs(argv) {
  const [command, ...args] = argv;
  if (!Object.hasOwn(optionsByCommand, command)) throw new TypeError('Unknown spine command');
  const options = {};
  for (let i = 0; i < args.length; i += 2) {
    const key = args[i].slice(2);
    if (!args[i].startsWith('--') || !['ledger', ...optionsByCommand[command]].includes(key)
        || Object.hasOwn(options, key) || !args[i + 1]?.trim() || args[i + 1].startsWith('--')) {
      throw new TypeError(`Invalid, duplicate, or missing-value option: ${args[i]}`);
    }
    options[key] = args[i + 1];
  }
  const required = key => {
    if (!options[key]) throw new TypeError(`--${key} is required`);
    return options[key];
  };
  required('ledger');
  for (const key of optionsByCommand[command]) {
    if (!['zen-cmd', 'blocker', 'evidence'].includes(key)
        || (command === 'resolve-blocker' && key === 'evidence')) required(key);
  }
  return { command, options };
}

// The public plan spelling is depends_on; the ledger owns dependencies.
function readPlan(path) {
  const plan = readJson(path);
  if (!plan || typeof plan !== 'object' || !Array.isArray(plan.milestones)) {
    throw new TypeError('Plan must contain milestones');
  }
  return { ...plan, milestones: plan.milestones.map(m => {
    if (m.depends_on !== undefined && m.dependencies !== undefined
        && JSON.stringify(m.depends_on) !== JSON.stringify(m.dependencies)) {
      throw new TypeError('Conflicting depends_on and dependencies');
    }
    return { ...m, dependencies: m.depends_on ?? m.dependencies };
  }) };
}

export function invokeExternalZen(command, request) {
  // This is explicitly a supervisor-supplied shell command, not candidate text.
  const output = spawnSync(command, {
    shell: true, input: JSON.stringify(request) + '\n', encoding: 'utf8',
    timeout: 90000, maxBuffer: 20 * 1024 * 1024,
  });
  if (output.error) throw output.error;
  if (output.status !== 0) throw new Error(`Zen command failed (${output.status}): ${output.stderr}`);
  let verdict = JSON.parse(output.stdout);
  // Official AGY JSON output wraps the role's JSON response in SUCCESS.
  if (verdict?.status === 'SUCCESS' && typeof verdict.response === 'string') {
    verdict = JSON.parse(verdict.response);
  }
  return verdict;
}

async function runMilestone(path, milestone, zenCommand, invokeRole) {
  // A fresh ledger validates transition errors using its original error types
  // before MinimalSpine's generic busy check. This copy is never saved.
  AuthoritativeLedger.load(path).delegate(milestone);
  let handoff;
  const handedOff = new Promise(resolveHandoff => { handoff = resolveHandoff; });
  const spine = new MinimalSpine({
    ledgerPath: path, invokeRole,
    invokeZen: zenCommand ? request => invokeExternalZen(zenCommand, request) : request => {
      handoff({ status: 'AWAITING_ZEN', verified: false, zen_request: request });
      // Suspend only this in-memory coordinator at the durable review boundary.
      // No timers or process handles remain. record-zen resumes from disk in a
      // fresh invocation; never fake a verdict or throw (which records failure).
      return new Promise(() => {});
    },
  });
  const running = spine.runMilestone(milestone);
  return zenCommand ? running : Promise.race([running, handedOff]);
}

/** Injectable role transport for deterministic tests; ledger and spine stay real. */
export async function execute(argv, { invokeRole = invoke } = {}) {
  const { command, options: o } = parseArgs(argv);
  const path = o.ledger;
  if (command === 'run-milestone') {
    return { ok: true, ...await runMilestone(path, o.milestone, o['zen-cmd'], invokeRole) };
  }
  const ledger = command === 'init' && !existsSync(path)
    ? new AuthoritativeLedger() : AuthoritativeLedger.load(path);
  let result;
  switch (command) {
    case 'init': ledger.init(readPlan(o.plan)); result = { state: ledger.getState() }; break;
    case 'status': result = { state: ledger.getState() }; break;
    case 'delegate': result = { packet: ledger.delegate(o.milestone) }; break;
    case 'candidate': result = ledger.receiveCandidate(readJson(o.file)); break;
    case 'record-zen': {
      const verdict = readJson(o.file);
      if (verdict?.verdict === 'GO') result = { verification: ledger.recordZenGo(verdict) };
      else if (verdict?.verdict === 'NO-GO') result = { verification: ledger.recordZenNoGo(verdict) };
      else throw new InvalidTransitionError('Zen verdict must be GO or NO-GO');
      break;
    }
    case 'blocked':
      if (!['BLOCKED', 'FAILED'].includes(o.status)) throw new InvalidTransitionError('Status must be BLOCKED or FAILED');
      result = ledger.recordBlockedOrFailure({
        milestoneId: o.milestone, status: o.status, blockers: o.blocker,
        evidence: o.evidence ? { classification: 'OBSERVED', result: o.evidence } : undefined,
      });
      break;
    case 'replan': ledger.materialReplan(readPlan(o.plan)); result = { state: ledger.getState() }; break;
    case 'resolve-blocker': result = ledger.resolveBlocker(o.id, { classification: 'OBSERVED', result: o.evidence }); break;
    case 'complete': result = ledger.declareGlobalCompletion(); break;
    case 'invoke-role': {
      result = await invokeRole(o.role, readJson(o.packet));
      if (!result?.ok) {
        return { ...result, ok: false, error: result?.error ?? 'Invocation failed',
          errorType: result?.errorType ?? result?.error ?? 'InvocationError' };
      }
      break;
    }
  }
  ledger.save(path);
  return { ok: true, ...result };
}

export async function main(argv) {
  try {
    return await execute(argv);
  } catch (error) {
    return { ok: false, error: error.message, errorType: error.name };
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const result = await main(process.argv.slice(2));
  console.log(JSON.stringify(result));
  process.exitCode = result.ok ? 0 : 1;
}

